// The collections-ux 1.2 duty: the watched-toggle write endpoint — the state
// strict parse, the photo gate, the unknown-item 404, the watched write's
// ledger-without-position-touch, the never-started item's zero-position
// mapping, and the unwatched clear. All asserted over the REAL router wiring
// and a real store, the repo's handler-test idiom (newProgressAPI helpers).
func putItemStateBody(t *testing.T, h http.Handler, itemID, body string) *http.Response {
	t.Helper()
	return doRequest(t, h, http.MethodPut, "/api/v1/items/"+itemID+"/state", body, adminToken)
}

// listProgressIDs fires the default continue rail and returns the served
// item ids in order.
func listProgressIDs(t *testing.T, h http.Handler, query string) []string {
	t.Helper()
	resp := doRequest(t, h, http.MethodGet, "/api/v1/progress"+query, "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("GET /progress%s status = %d, want %d", query, resp.StatusCode, http.StatusOK)
	}
	lr := decodeProgressList(t, resp)
	ids := make([]string, len(lr.Items))
	for i, d := range lr.Items {
		ids[i] = d.ItemID
	}
	return ids
}

func containsID(ids []string, want string) bool {
	for _, id := range ids {
		if id == want {
			return true
		}
	}
	return false
}

// TestPutItemStateWatched covers the ledger-without-position-touch contract:
// a watched write against an item holding a mid-media position echoes 200
// watched with the UNCHANGED position, ledgers the row, and leaves the
// progress record intact — the default rail withdraws the row (completed
// watches have no resume point) and ?include=watched restores it stamped
// watched. A repeat write is a no-op on the ledger (the idempotent PK).
func TestPutItemStateWatched(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	ctx := context.Background()
	itemID := "itm_sw"
	seedItem(t, st, libID, "sw", "S S01E01.mkv")
	if _, err := st.PutProgress(ctx, itemID, 3720); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}

	resp := putItemStateBody(t, h, itemID, `{"state": "watched"}`)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var dto itemStateDTO
	if err := json.NewDecoder(resp.Body).Decode(&dto); err != nil {
		t.Fatalf("decode itemStateDTO: %v", err)
	}
	if dto.ItemID != itemID || dto.State != itemStateWatched || dto.PositionSeconds != 3720 {
		t.Fatalf("DTO = %+v, want item_id %s watched position 3720 (unchanged)", dto, itemID)
	}
	if dto.CompletedAt == "" {
		t.Fatalf("completed_at must be present on a watched echo")
	}
	if _, err := time.Parse(time.RFC3339, dto.CompletedAt); err != nil {
		t.Fatalf("completed_at %q is not RFC3339: %v", dto.CompletedAt, err)
	}

	// The ledger carries the row, the stored position is untouched, and the
	// rail reflects both facts: default withdrawal, include=watched restore.
	watched, err := st.ListWatched(ctx)
	if err != nil {
		t.Fatalf("ListWatched: %v", err)
	}
	if len(watched) != 1 || watched[0] != itemID {
		t.Fatalf("ListWatched = %v, want [%s]", watched, itemID)
	}
	rec, err := st.GetProgress(ctx, itemID)
	if err != nil || rec.PositionSeconds != 3720 {
		t.Fatalf("GetProgress = (%+v, %v), want position 3720 untouched", rec, err)
	}
	if ids := listProgressIDs(t, h, ""); containsID(ids, itemID) {
		t.Fatalf("default rail = %v, watched item must be withdrawn", ids)
	}
	includeResp := doRequest(t, h, http.MethodGet, "/api/v1/progress?include=watched&sort=recent", "", adminToken)
	defer includeResp.Body.Close()
	lr := decodeProgressList(t, includeResp)
	if len(lr.Items) != 1 || lr.Items[0].ItemID != itemID || !lr.Items[0].Watched || lr.Items[0].PositionSeconds != 3720 {
		t.Fatalf("include=watched rows = %+v, want %s watched at 3720", lr.Items, itemID)
	}

	// The repeat write is a no-op on the ledger.
	repeat := putItemStateBody(t, h, itemID, `{"state": "watched"}`)
	defer repeat.Body.Close()
	if repeat.StatusCode != http.StatusOK {
		t.Fatalf("repeat status = %d, want %d", repeat.StatusCode, http.StatusOK)
	}
	watched, err = st.ListWatched(ctx)
	if err != nil {
		t.Fatalf("ListWatched after repeat: %v", err)
	}
	if len(watched) != 1 || watched[0] != itemID {
		t.Fatalf("ListWatched after repeat = %v, want exactly [%s]", watched, itemID)
	}
}

// TestPutItemStateWatchedFreshItem covers the never-started item: a watched
// write against an item holding NO progress record at all is 200 with
// position_seconds 0 — the post-write read's missing row maps to zero, never
// an error — the ledger row IS inserted, and the item stays absent from the
// default progress listing (its position is not positive).
func TestPutItemStateWatchedFreshItem(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	ctx := context.Background()
	itemID := "itm_fresh"
	seedItem(t, st, libID, "fresh", "F S01E01.mkv")

	resp := putItemStateBody(t, h, itemID, `{"state": "watched"}`)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var dto itemStateDTO
	if err := json.NewDecoder(resp.Body).Decode(&dto); err != nil {
		t.Fatalf("decode itemStateDTO: %v", err)
	}
	if dto.ItemID != itemID || dto.State != itemStateWatched || dto.PositionSeconds != 0 {
		t.Fatalf("DTO = %+v, want item_id %s watched position 0 (no-row mapped to zero)", dto, itemID)
	}
	if dto.CompletedAt == "" {
		t.Fatalf("completed_at must be present on a watched echo")
	}
	watched, err := st.ListWatched(ctx)
	if err != nil {
		t.Fatalf("ListWatched: %v", err)
	}
	if len(watched) != 1 || watched[0] != itemID {
		t.Fatalf("ListWatched = %v, want [%s]", watched, itemID)
	}
	if ids := listProgressIDs(t, h, ""); containsID(ids, itemID) {
		t.Fatalf("default rail = %v, zero-position item must stay absent", ids)
	}
}

// TestPutItemStateUnwatched covers the clear: unwatching a ledgered item
// holding a positive position deletes the ledger row AND zeroes the position
// (one store transaction), the echo is unwatched at position 0 with NO
// completed_at, and the default rail omits the item.
func TestPutItemStateUnwatched(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	ctx := context.Background()
	itemID := "itm_uw"
	seedItem(t, st, libID, "uw", "U S01E01.mkv")
	if _, err := st.PutProgress(ctx, itemID, 3720); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	if err := st.InsertWatched(ctx, itemID, libID, "", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}

	resp := putItemStateBody(t, h, itemID, `{"state": "unwatched"}`)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var dto itemStateDTO
	if err := json.NewDecoder(resp.Body).Decode(&dto); err != nil {
		t.Fatalf("decode itemStateDTO: %v", err)
	}
	if dto.ItemID != itemID || dto.State != itemStateUnwatched || dto.PositionSeconds != 0 {
		t.Fatalf("DTO = %+v, want item_id %s unwatched position 0", dto, itemID)
	}
	if dto.CompletedAt != "" {
		t.Fatalf("completed_at = %q, want absent on an unwatched echo", dto.CompletedAt)
	}
	watched, err := st.ListWatched(ctx)
	if err != nil {
		t.Fatalf("ListWatched: %v", err)
	}
	if len(watched) != 0 {
		t.Fatalf("ListWatched = %v, want empty (row gone)", watched)
	}
	rec, err := st.GetProgress(ctx, itemID)
	if err != nil || rec.PositionSeconds != 0 {
		t.Fatalf("GetProgress = (%+v, %v), want position reset to 0", rec, err)
	}
	if ids := listProgressIDs(t, h, ""); containsID(ids, itemID) {
		t.Fatalf("default rail = %v, zeroed item must be omitted", ids)
	}
}

// TestPutItemStateValidation is the write-endpoint rejection table: an
// unknown state string and a malformed body are 400 bad_request, a
// photo-module item is 400 bad_request, an unknown item is 404 not_found —
// and no ledger or progress row is touched in any case.
func TestPutItemStateValidation(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	ctx := context.Background()
	seedItem(t, st, libID, "val", "V S01E01.mkv")
	if _, err := st.PutProgress(ctx, "itm_val", 900); err != nil {
		t.Fatalf("PutProgress: %v", err)
	}
	photoLib, err := st.CreateLibrary(ctx, "image", "/media/photos", "Photos")
	if err != nil {
		t.Fatalf("CreateLibrary photo: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: "itm_photo", ModuleID: "image", LibraryID: photoLib, FileID: "photo",
		RelativePath: "p.jpg", MediaType: "image",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem photo: %v", err)
	}

	cases := []struct {
		name string
		item string
		body string
		code string
		want int
	}{
		{"unknown_state", "itm_val", `{"state": "skipped"}`, "bad_request", http.StatusBadRequest},
		{"missing_state", "itm_val", `{}`, "bad_request", http.StatusBadRequest},
		{"malformed_json", "itm_val", `not json`, "bad_request", http.StatusBadRequest},
		{"photo_item", "itm_photo", `{"state": "watched"}`, "bad_request", http.StatusBadRequest},
		{"unknown_item", "itm_nope", `{"state": "watched"}`, "not_found", http.StatusNotFound},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			resp := putItemStateBody(t, h, tc.item, tc.body)
			defer resp.Body.Close()
			if resp.StatusCode != tc.want {
				t.Fatalf("status = %d, want %d", resp.StatusCode, tc.want)
			}
			eb := decodeError(t, resp)
			if eb.Error.Code != tc.code || eb.Error.Retryable {
				t.Fatalf("error body = %+v, want %s/non-retryable", eb.Error, tc.code)
			}
		})
	}

	// No ledger or progress row was touched by any rejection.
	watched, err := st.ListWatched(ctx)
	if err != nil {
		t.Fatalf("ListWatched: %v", err)
	}
	if len(watched) != 0 {
		t.Fatalf("ListWatched = %v, want empty (rejections touch nothing)", watched)
	}
	rec, err := st.GetProgress(ctx, "itm_val")
	if err != nil || rec.PositionSeconds != 900 {
		t.Fatalf("GetProgress itm_val = (%+v, %v), want position 900 untouched", rec, err)
	}
	if _, err := st.GetProgress(ctx, "itm_photo"); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("GetProgress itm_photo err = %v, want sql.ErrNoRows (photo never ledged or progressed)", err)
	}
}
